        const floorGeo = new THREE.BoxGeometry(BUILDING_WIDTH - SHAFT_WIDTH - 4, 0.2, BUILDING_DEPTH / 2);
        const floorMat = new THREE.MeshBasicMaterial({ color: 0xcccccc, transparent: true, opacity: 0.3 });
