test.describe('Elevator Simulation', () => {
    test.beforeAll(async ({ page }) => {
        await page.goto('http://localhost:3000/index.html');
        // Wait for the simulation to load
        await page.waitForTimeout(2000);
    });

    test('should have a visible nonblank Three.js canvas', async ({ page }) => {
        const canvas = await page.locator('canvas');
        expect(canvas).toBeVisible();

        // Check that the canvas has content (non-blank)
        const rect = await canvas.boundingBox();
        expect(rect.width).toBeGreaterThan(0);
        expect(rect.height).toBeGreaterThan(0);
    });

    test('should have animation frames observed', async ({ page }) => {
        // Wait for some time to see if there's animation
        await page.waitForTimeout(3000);

        // Check that the canvas has changed (by taking a screenshot)
        const screenshot1 = await page.screenshot();
        await page.waitForTimeout(2000);
        const screenshot2 = await page.screenshot();

        // Screenshots should be different if there's animation
        expect(screenshot1).not.toBeEqualTo(screenshot2);
    });

    test('should have scene objects observed', async ({ page }) => {
