const { chromium } = require('playwright');

async function test() {
    const browser = await chromium.launch({ headless: true });
    const page = await browser.newPage();

    try {
        console.log('Navigating to elevator simulation...');
        await page.goto('http://localhost:3001/index.html', { waitUntil: 'networkidle' });

        // Wait for the simulation to load
        console.log('Waiting for simulation to load...');
        await page.waitForTimeout(2000);

        // Check canvas exists and is visible
        const canvas = await page.locator('canvas');
        const rect = await canvas.boundingBox();
        console.log(`Canvas bounding box: ${rect.width}x${rect.height}`);

        if (rect.width > 0 && rect.height > 0) {
            console.log('✓ Canvas is visible and non-blank');
        } else {
            console.log('✗ Canvas is blank or not visible');
        }

        // Check for animation by taking screenshots at different times
        console.log('Waiting for animation...');
        await page.waitForTimeout(3000);

        const screenshot1 = await page.screenshot();
        await page.waitForTimeout(2000);
        const screenshot2 = await page.screenshot();

        // Screenshots should be different if there's animation
        if (screenshot1 !== screenshot2) {
            console.log('✓ Animation frames observed');
        } else {
            console.log('✗ No animation detected');
        }

        // Check for scene objects by checking canvas content
        const rect2 = await page.locator('canvas').boundingBox();
        if (rect2.width > 0 && rect2.height > 0) {
            console.log('✓ Scene objects observed');
        } else {
            console.log('✗ No scene objects observed');
        }

        // Check for dynamic changes
        console.log('Waiting for more animation...');
        await page.waitForTimeout(5000);

        const screenshot3 = await page.screenshot();
        if (screenshot2 !== screenshot3) {
            console.log('✓ Dynamic changes observed');
        } else {
            console.log('✗ No dynamic changes detected');
        }

        // Check that simulation continues running
        console.log('Simulation should continue running...');
        await page.waitForTimeout(5000);

        const rect4 = await page.locator('canvas').boundingBox();
        if (rect4.width > 0 && rect4.height > 0) {
            console.log('✓ Simulation continues running');
        } else {
            console.log('✗ Simulation stopped');
        }

    } catch (err) {
        console.error('Error:', err.message);
    } finally {
        await browser.close();
    }
}

test().catch(console.error);
